    <script>
        const inputs = Array.from(document.querySelectorAll('.otp-box'));
        const verifyBtn = document.getElementById('verifyBtn');
        const timerEl = document.getElementById('timer');
        const countdownWrapper = document.getElementById('countdownWrapper');
        const resendBtn = document.getElementById('resendBtn');

        let timeLeft = 45;
        let timerInterval = null;

        // Auto-focus and navigation logic for 6 OTP boxes
        inputs.forEach((input, index) => {
            // Handle keydown for Backspace navigation
            input.addEventListener('keydown', (e) => {
                if (e.key === 'Backspace') {
                    if (!input.value && index > 0) {
                        inputs[index - 1].focus();
                        inputs[index - 1].value = '';
                        inputs[index - 1].classList.remove('filled');
                        checkCompletion();
                    } else {
                        input.value = '';
                        input.classList.remove('filled');
                        checkCompletion();
                    }
                }
            });

            // Handle numeric inputs and auto-advance
            input.addEventListener('input', (e) => {
                let val = e.target.value.replace(/[^0-9]/g, ''); // Ensure only numbers
                if (val.length > 0) {
                    input.value = val[val.length - 1]; // take latest typed digit
                    input.classList.add('filled');
                    if (index < inputs.length - 1) {
                        inputs[index + 1].focus();
                    }
                } else {
                    input.classList.remove('filled');
                }
                checkCompletion();
            });

            // Handle Paste event for quick OTP fill
            input.addEventListener('paste', (e) => {
                e.preventDefault();
                const pastedData = (e.clipboardData || window.clipboardData).getData('text');
                const cleanDigits = pastedData.replace(/\D/g, '').slice(0, 6);

                cleanDigits.split('').forEach((char, i) => {
                    if (inputs[i]) {
                        inputs[i].value = char;
                        inputs[i].classList.add('filled');
                    }
                });

                if (cleanDigits.length > 0) {
                    const nextFocusIndex = Math.min(cleanDigits.length, inputs.length - 1);
                    inputs[nextFocusIndex].focus();
                }
                checkCompletion();
            });
        });

        function checkCompletion() {
            const allFilled = inputs.every(input => input.value.trim().length === 1);
            verifyBtn.disabled = !allFilled;
        }

        // Countdown Timer Logic
        function startTimer() {
            clearInterval(timerInterval);
            countdownWrapper.style.display = 'inline-flex';
            resendBtn.style.display = 'none';

            timerInterval = setInterval(() => {
                timeLeft--;
                const minutes = Math.floor(timeLeft / 60);
                const seconds = timeLeft % 60;
                timerEl.textContent = `${minutes}:${seconds < 10 ? '0' : ''}${seconds}`;

                if (timeLeft <= 0) {
                    clearInterval(timerInterval);
                    countdownWrapper.style.display = 'none';
                    resendBtn.style.display = 'inline-block';
                }
            }, 1000);
        }

        function restartTimer() {
            timeLeft = 45;
            timerEl.textContent = '0:45';
            startTimer();
            // Reset input boxes focus
            inputs[0].focus();
        }

        function handleVerify() {
            const enteredCode = inputs.map(input => input.value).join('');
            verifyBtn.innerHTML = `<span>جارٍ التحقق...</span>`;
            verifyBtn.disabled = true;

            setTimeout(() => {
                alert(`تم تأكيد الرمز بنجاح: ${enteredCode}`);
                verifyBtn.innerHTML = `<span>تأكيد</span>`;
                verifyBtn.disabled = false;
            }, 800);
        }

        // Initialize countdown on load
        startTimer();
    </script>
